/* Dashboard page ---------------------------------------------------------- */

.dashboard {
    /* DashKit CSS API */
    --dashkit-grid-item-border-radius: var(--g-border-radius-l);
    --dashkit-grid-item-edit-opacity: 0.85;
    --dashkit-overlay-color: var(--g-color-base-simple-hover);
    --dashkit-overlay-border-color: var(--g-color-line-brand);
    --dashkit-placeholder-color: var(--g-color-base-brand);
    --dashkit-placeholder-opacity: 0.15;

    box-sizing: border-box;
    min-height: 100vh;
    padding: var(--g-spacing-6);
    background: var(--g-color-base-generic-ultralight);
}

.dashboard_edit {
    /* room for the fixed ActionPanel so it never covers the last row */
    padding-bottom: calc(var(--g-spacing-10) * 3);
}

.dashboard__toolbar {
    margin-bottom: var(--g-spacing-5);
}

.dashboard__heading {
    flex: 1 1 320px;
    min-width: 0;
}

.dashboard__actions {
    flex-shrink: 0;
}

.dashboard__grid {
    position: relative;
    min-height: 240px;
}

.dashboard_edit .dashboard__grid {
    border-radius: var(--g-border-radius-l);
    outline: 1px dashed var(--g-color-line-generic);
    outline-offset: var(--g-spacing-1);
}

.dashboard__empty {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--g-spacing-1);
    text-align: center;
    pointer-events: none;
}

/* Widgets ----------------------------------------------------------------- */

.widget {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: var(--g-spacing-2);
    height: 100%;
    padding: var(--g-spacing-4);
    overflow: hidden;
    border-radius: var(--g-border-radius-l);
    border: 1px solid var(--g-color-line-generic);
    background: var(--g-color-base-float);
}

.widget__title {
    flex-shrink: 0;
}

.widget__body {
    position: relative;
    flex: 1;
    min-height: 0;
    min-width: 0;
}

.widget__chart {
    position: absolute;
    inset: 0;
}

.widget__scroll {
    position: absolute;
    inset: 0;
    overflow: auto;
}

.widget_metric {
    justify-content: center;
    gap: var(--g-spacing-1);
}

.widget__metric-value {
    font-variant-numeric: tabular-nums;
}

.widget__no-shrink {
    flex-shrink: 0;
}

/* Built-in "title" / "text" plugins: keep them aligned with card padding. */
.dashboard .dashkit-plugin-text {
    box-sizing: border-box;
    height: 100%;
    padding: var(--g-spacing-4);
    border-radius: var(--g-border-radius-l);
    background: var(--g-color-base-info-light);
    color: var(--g-color-text-primary);
    overflow: auto;
}

@media (max-width: 600px) {
    .dashboard {
        padding: var(--g-spacing-3);
    }
}

